//	recipientEmail: The email address to send the test email to.
func SendAuthEmailProviderTest(ctx context.Context, clientConfig ClientConfig, params SendAuthEmailProviderTestParams, opts ...RequestOption) (*SendNeonAuthTestEmailResponse, error) {
	projectId := params.ProjectId
	branchId := params.BranchId
	recipientEmail := params.RecipientEmail

	if err := ValidatePattern("project_id", projectId, "^[a-z0-9-]{1,60}$"); err != nil {
		return nil, err
	}

	if err := ValidatePattern("branch_id", branchId, "^[a-z0-9-]{1,60}$"); err != nil {
		return nil, err
	}

	if err := ValidateLength("recipient_email", recipientEmail, LengthOpts{Min: Ptr[int](1), Max: Ptr[int](256)}); err != nil {
		return nil, err
	}
	if err := ValidateEmail("recipient_email", recipientEmail); err != nil {
		return nil, err
	}

	resp, err := DoCfg[SendNeonAuthTestEmailResponse](ctx, &clientConfig, "POST", fmt.Sprintf("/projects/%s/branches/%s/auth/email_provider/test", EncodePathSegment(projectId), EncodePathSegment(branchId)), &RequestOpts{
		Body: map[string]any{
			"recipient_email": recipientEmail,
		},
		OperationID: "SendAuthEmailProviderTest",
		Errors:      ErrorDecoders{"default": decodeErrorData[GeneralError]},
		Options:     opts,
	})
	if err != nil {
		return nil, err
	}
	return &resp.Data, nil
}

